import uuid
from datetime import datetime

from sqlalchemy import CheckConstraint, DateTime, ForeignKey, UniqueConstraint, func
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column


class Base(DeclarativeBase):
    pass


class User(Base):
    """A global account. Which studios it belongs to is decided by memberships (step 8)."""

    __tablename__ = "users"

    # Generated by Postgres, so any writer (app, seed script, raw SQL) gets an id.
    id: Mapped[uuid.UUID] = mapped_column(primary_key=True, server_default=func.gen_random_uuid())
    # ponytail: case-sensitive unique; login lowercases the email it looks up, so any signup/invite code must store it lowercased too.
    email: Mapped[str] = mapped_column(unique=True)
    name: Mapped[str]
    locale: Mapped[str] = mapped_column(server_default="en")
    # Argon2 hash, never the password. NULL = no password login (e.g. Google sign-in, step 53).
    password_hash: Mapped[str | None]


class Tenant(Base):
    """One studio. Every tenant-owned table later carries a tenant_id pointing here."""

    __tablename__ = "tenants"

    id: Mapped[uuid.UUID] = mapped_column(primary_key=True, server_default=func.gen_random_uuid())
    name: Mapped[str]
    # ponytail: any string accepted; check format (lowercase, URL-safe) at the API boundary.
    slug: Mapped[str] = mapped_column(unique=True)
    # IANA name such as "Asia/Jerusalem", never an offset (offsets change with DST).
    # ponytail: not validated here; check with zoneinfo when sessions are created (step 18).
    timezone: Mapped[str]
    default_locale: Mapped[str] = mapped_column(server_default="en")


class Membership(Base):
    """Links a user to a studio with a role, so one account can belong to several studios."""

    __tablename__ = "memberships"
    __table_args__ = (
        UniqueConstraint("tenant_id", "user_id"),
        # CHECK rather than a Postgres ENUM: adding a role (head_coach, step 48) is a plain
        # drop + add of this constraint.
        CheckConstraint("role IN ('owner', 'coach', 'member')", name="ck_memberships_role"),
    )

    id: Mapped[uuid.UUID] = mapped_column(primary_key=True, server_default=func.gen_random_uuid())
    tenant_id: Mapped[uuid.UUID] = mapped_column(ForeignKey("tenants.id"))
    user_id: Mapped[uuid.UUID] = mapped_column(ForeignKey("users.id"))
    role: Mapped[str]


class RefreshToken(Base):
    """A long-lived login credential. Only its SHA-256 hash is stored, never the token itself."""

    __tablename__ = "refresh_tokens"

    id: Mapped[uuid.UUID] = mapped_column(primary_key=True, server_default=func.gen_random_uuid())
    user_id: Mapped[uuid.UUID] = mapped_column(ForeignKey("users.id"))
    # Unique: lookups go by this value, and the unique index makes them fast.
    token_hash: Mapped[str] = mapped_column(unique=True)
    # timezone=True: store a real UTC instant, not a naive wall-clock time.
    expires_at: Mapped[datetime] = mapped_column(DateTime(timezone=True))
    # NULL = still usable. Set when the token is cancelled (logout), never cleared again.
    revoked_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
